<?php
require 'config.php';require_login();$uid=(int)$_SESSION['user_id'];$preferences=user_preferences($pdo,$uid);$error='';$name=$_SESSION['full_name'];
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=input_string('action');
 if($action==='preferences'){
  $name=input_string('full_name');$preferences['quiet_start']=input_string('quiet_start');$preferences['quiet_end']=input_string('quiet_end');$preferences['preferred_hour']=(int)input_string('preferred_hour');$preferences['notifications_enabled']=isset($_POST['notifications_enabled']);
  if($name===''||mb_strlen($name)>100)$error='Enter a name between 1 and 100 characters.';
  elseif(!preg_match('/^([01]\d|2[0-3]):[0-5]\d$/',$preferences['quiet_start'])||!preg_match('/^([01]\d|2[0-3]):[0-5]\d$/',$preferences['quiet_end']))$error='Choose valid quiet-hour times.';
  elseif(!ctype_digit(input_string('preferred_hour'))||$preferences['preferred_hour']<0||$preferences['preferred_hour']>23)$error='Choose a preferred reminder hour between 0 and 23.';
  else{
   $pdo->beginTransaction();
   try{$pdo->prepare('UPDATE users SET full_name=? WHERE user_id=?')->execute([$name,$uid]);$pdo->prepare('INSERT INTO app_preferences(user_id,quiet_start,quiet_end,preferred_hour,notifications_enabled) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE quiet_start=VALUES(quiet_start),quiet_end=VALUES(quiet_end),preferred_hour=VALUES(preferred_hour),notifications_enabled=VALUES(notifications_enabled)')->execute([$uid,$preferences['quiet_start'],$preferences['quiet_end'],$preferences['preferred_hour'],(int)$preferences['notifications_enabled']]);$pdo->commit();$_SESSION['full_name']=$name;flash('success','Your preferences are saved.');redirect('settings.php');}catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();$error='We could not save your preferences. Please try again.';}
  }
 }elseif($action==='add_category'){
  $category=input_string('category_name');
  if($category===''||mb_strlen($category)>80)$error='Use a category name between 1 and 80 characters.';
  else{$q=$pdo->prepare('SELECT category_id FROM categories WHERE (user_id IS NULL OR user_id=?) AND category_name=?');$q->execute([$uid,$category]);if($q->fetch())$error='That category already exists.';else{$pdo->prepare('INSERT INTO categories(user_id,category_name,is_system) VALUES(?,?,0)')->execute([$uid,$category]);flash('success','Category added.');redirect('settings.php');}}
 }elseif($action==='delete_category'){
  try{$delete=$pdo->prepare('DELETE FROM categories WHERE category_id=? AND user_id=? AND is_system=0');$delete->execute([(int)input_string('category_id'),$uid]);if($delete->rowCount()){flash('success','Category removed. Its tasks are now uncategorised.');redirect('settings.php');}$error='This category is unavailable or cannot be removed.';}catch(PDOException $ex){error_log('Category removal failed: '.$ex->getCode());$error='We could not remove this category. Please try again.';}
 }else{$error='Choose a valid settings action.';}
}
$q=$pdo->prepare('SELECT * FROM categories WHERE user_id IS NULL OR user_id=? ORDER BY is_system DESC,category_name');$q->execute([$uid]);$categories=$q->fetchAll();$pageTitle='Settings';include 'includes/header.php';?>
<main id="main-content" class="container"><div class="page-heading"><div><p class="eyebrow">MAKE THIS SPACE YOURS</p><h1>Settings</h1><p class="muted">Small preferences that make a more thoughtful day.</p></div></div>
<?php if($error):?><div class="flash error" role="alert"><?=e($error)?></div><?php endif;?><div class="cards"><section class="panel"><div class="panel-head"><h2>Your preferences</h2><?=icon('settings')?></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="preferences"><div class="wide"><label for="full_name">Display name</label><input id="full_name" name="full_name" maxlength="100" value="<?=e($name)?>" required></div><div class="wide"><label>Account time zone</label><p><?=e($preferences['timezone'])?></p><p class="field-help">Set at registration. Existing deadlines use this local time zone.</p></div><div><label for="quiet_start">Quiet hours begin</label><input type="time" id="quiet_start" name="quiet_start" value="<?=e($preferences['quiet_start'])?>" required></div><div><label for="quiet_end">Quiet hours end</label><input type="time" id="quiet_end" name="quiet_end" value="<?=e($preferences['quiet_end'])?>" required></div><p class="field-help wide">No in-app or browser alerts during quiet hours. Matching start and end times turn quiet hours off. Due alerts wait until quiet hours end.</p><div class="wide"><label for="preferred_hour">Preferred reminder hour</label><select id="preferred_hour" name="preferred_hour"><?php for($hour=0;$hour<24;$hour++):?><option value="<?=$hour?>" <?=$hour===$preferences['preferred_hour']?'selected':''?>><?=sprintf('%02d:00',$hour)?></option><?php endfor;?></select><p class="field-help">Used until the AI has at least three recent completed tasks to learn from.</p></div><div class="wide"><label class="checkbox-label"><input type="checkbox" name="notifications_enabled" value="1" <?=$preferences['notifications_enabled']?'checked':''?>> Enable reminder alerts</label><p class="field-help">Reminders appear while SmartTask is open. Browser notifications require your permission; background and email delivery are not included.</p><button class="btn secondary" id="enable-notifications" type="button">Enable browser notifications</button></div><div class="wide"><button class="btn primary">Save preferences</button></div></form></section>
<section class="panel"><div class="panel-head"><h2>Task categories</h2><span class="pill"><?=count($categories)?></span></div><p class="muted">Keep related responsibilities together.</p><div class="category-list"><?php foreach($categories as $c):?><div class="reminder"><div class="panel-head"><strong><?=e($c['category_name'])?></strong><?php if($c['is_system']):?><span class="pill">Default</span><?php else:?><form method="post" data-confirm="Remove this category? Its tasks will be kept as uncategorised."><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="delete_category"><input type="hidden" name="category_id" value="<?=$c['category_id']?>"><button class="btn danger small" aria-label="Remove <?=e($c['category_name'])?>"><?=icon('trash')?></button></form><?php endif;?></div></div><?php endforeach;?></div><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="add_category"><label for="category_name">New category</label><input id="category_name" name="category_name" maxlength="80" placeholder="e.g. Dissertation" required><button class="btn secondary" style="margin-top:12px">Add category</button></form></section></div></main><?php include 'includes/footer.php';?>
